package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;import java.text.SimpleDateFormat;
public class RefreshActivity extends BooksActivity {
 @Override void page(String title){super.page(title);LinearLayout shell=new LinearLayout(this);shell.setBackgroundColor(0xff0c1020);sidebar=new LinearLayout(this);sidebar.setOrientation(1);sidebar.setPadding(dp(10),dp(20),dp(10),dp(12));sidebar.setBackgroundColor(0xff101629);shell.addView(sidebar,new LinearLayout.LayoutParams(dp(86),-1));TextView brand=new TextView(this);brand.setText("SKY");brand.setTextSize(18);brand.setTextColor(0xffb4c7ff);brand.setTypeface(Typeface.DEFAULT_BOLD);brand.setGravity(Gravity.CENTER);sidebar.addView(brand,new LinearLayout.LayoutParams(-1,dp(58)));rail("Home",0,()->home());rail("Books",1,()->bookshelf());rail("Create",2,()->drawing(false));rail("Photos",3,()->startGallery(false));rail("Play",4,()->puzzle());View spacer=new View(this);sidebar.addView(spacer,new LinearLayout.LayoutParams(1,0,1));rail("Settings",9,()->settings());LinearLayout main=new LinearLayout(this);main.setOrientation(1);main.setPadding(dp(22),dp(16),dp(22),0);shell.addView(main,new LinearLayout.LayoutParams(0,-1,1));header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);main.addView(header,new LinearLayout.LayoutParams(-1,dp(60)));TextView heading=new TextView(this);heading.setText(title);heading.setTextSize(27);heading.setTextColor(fg);heading.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));mini(header,"Full",()->expandPage(true));mini(header,"Rotate",()->screenRotation());ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);main.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,dp(14),0,dp(28));scroll.addView(body);wrapper=new FrameLayout(this);wrapper.addView(shell);exitExpanded=new TextView(this);exitExpanded.setText("Exit fullscreen");exitExpanded.setTextColor(fg);exitExpanded.setPadding(dp(16),dp(14),dp(16),dp(14));exitExpanded.setBackground(press(surface));exitExpanded.setVisibility(View.GONE);FrameLayout.LayoutParams exit=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.RIGHT);exit.setMargins(0,0,dp(16),dp(16));wrapper.addView(exitExpanded,exit);exitExpanded.setOnClickListener(v->expandPage(false));setContentView(wrapper);}
 void rail(String title,int icon,Runnable action){LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setPadding(0,dp(9),0,dp(9));item.addView(new Glyph(icon,0xffa6b8e5),new LinearLayout.LayoutParams(dp(24),dp(24)));TextView t=new TextView(this);t.setText(title);t.setTextColor(muted);t.setTextSize(11);t.setPadding(0,dp(5),0,0);item.addView(t);sidebar.addView(item,new LinearLayout.LayoutParams(-1,dp(66)));item.setBackground(press(0xff101629));item.setOnClickListener(v->action.run());}
 @Override void text(String value){TextView t=new TextView(this);t.setText(value);t.setTextColor(muted);t.setTextSize(17);t.setLineSpacing(dp(4),1.1f);t.setPadding(dp(2),dp(8),dp(2),dp(14));body.addView(t);}
 @Override void button(String value,Runnable action){if(value.equals("Import EPUB / text book"))value="Import book / PDF";LinearLayout card=new LinearLayout(this);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(16),dp(14),dp(14),dp(14));card.setBackground(press(0xff192238));int icon=value.toLowerCase(Locale.US).contains("book")?1:value.toLowerCase(Locale.US).contains("save")?5:0;card.addView(new Glyph(icon,0xffa7c7ff),new LinearLayout.LayoutParams(dp(22),dp(22)));TextView name=new TextView(this);name.setText(value);name.setTextColor(fg);name.setTextSize(16);name.setPadding(dp(14),0,dp(10),0);card.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=new TextView(this);arrow.setText(">");arrow.setTextColor(muted);card.addView(arrow);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(10);card.setMinimumHeight(dp(56));body.addView(card,cp);card.setOnClickListener(v->action.run());}
 @Override EditText input(String hint,String value){EditText edit=super.input(hint,value);edit.setBackgroundResource(local.skyfamily.R.drawable.sky_control);return edit;}
 int iconFor(String title){String t=title.toLowerCase(Locale.US);return t.contains("book")?1:t.contains("draw")||t.contains("colour")||t.contains("project")?2:t.contains("photo")||t.contains("immich")||t.contains("gallery")?3:t.contains("game")||t.contains("pet")?4:t.contains("note")||t.contains("calendar")?5:t.contains("space")?6:t.contains("explore")||t.contains("camera")?7:t.contains("news")?8:0;}
 @Override void tile(String title,String subtitle,String mark,int color,Runnable action){if(count%columns==0){grid=new LinearLayout(this);body.addView(grid);}LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(18),dp(18),dp(16));card.setBackground(press(0xff182136));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(158),1);cp.setMargins(dp(5),dp(5),dp(5),dp(5));grid.addView(card,cp);card.addView(new Glyph(iconFor(title),color),new LinearLayout.LayoutParams(dp(30),dp(30)));TextView name=new TextView(this);name.setText(title);name.setTextColor(fg);name.setTextSize(21);name.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));name.setPadding(0,dp(14),0,dp(5));card.addView(name);TextView desc=new TextView(this);desc.setText(subtitle);desc.setTextColor(muted);desc.setTextSize(13);desc.setMaxLines(2);card.addView(desc);card.setOnClickListener(v->action.run());card.setContentDescription(title+". "+subtitle);count++;}
 @Override void home(){page("Your everyday space");LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(dp(26),dp(24),dp(26),dp(24));android.graphics.drawable.GradientDrawable fill=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff314d82,0xff29324f});fill.setCornerRadius(dp(24));hero.setBackground(fill);TextView date=new TextView(this);date.setText(new SimpleDateFormat("EEEE / d MMMM",Locale.getDefault()).format(new Date()));date.setTextColor(0xffc6d5f3);date.setTextSize(14);hero.addView(date);TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(46);clock.setTextColor(Color.WHITE);clock.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));hero.addView(clock);TextView line=new TextView(this);line.setText("Make something. Read a little. Stay curious.");line.setTextColor(0xffd5e1f6);line.setTextSize(17);hero.addView(line);body.addView(hero);columns=getResources().getConfiguration().screenWidthDp>=950?3:2;count=0;section("Your collections");tile("Photo frame","Fullscreen memories from Immich","",0xff9ddfd3,()->startGallery(false));tile("Bookshelf","Books, PDFs and your reading place","",0xffadc7ff,()->bookshelf());tile("Calendar","Make room for what matters","",0xffffcf92,()->calendar());endgrid();section("Create and unwind");tile("Drawing","A blank canvas, ready for you","",0xffd0b4ff,()->drawing(false));tile("Colouring","Slow down and add some colour","",0xfff5b6cf,()->drawing(true));tile("Art projects","Reopen and continue your artwork","",0xff9ddfd3,()->projectsEntry());tile("Games","Word puzzles and arcade favourites","",0xffffcf92,()->puzzle());tile("Daily notes","Keep a thought for later","",0xffadc7ff,()->notes());tile("Pocket creature","A small companion to care for","",0xffd0b4ff,()->pet());endgrid();section("Explore");tile("Space","Stations, crew and APOD","",0xffadc7ff,()->space());tile("Live cameras","A window to somewhere else","",0xff9ddfd3,()->cameras());tile("News","Read your RSS stories here","",0xffffcf92,()->news());endgrid();button("Installed apps",()->apps());button("Receive images with QR",()->share());button("Uploaded images",()->uploads());button("Gallery and idle settings",()->gallerySettings());atHome=true;armIdle();}
 void projectsEntry(){toast("Open saved projects from the studio tools");}
 class Glyph extends View {final int kind,color;Paint pen=new Paint(3);Glyph(int k,int c){super(RefreshActivity.this);kind=k;color=c;}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/32f,getHeight()/32f);pen.setColor(color);pen.setStrokeWidth(2);pen.setStyle(Paint.Style.STROKE);pen.setStrokeCap(Paint.Cap.ROUND);if(kind==1){c.drawRoundRect(new RectF(4,5,28,27),3,3,pen);c.drawLine(16,5,16,27,pen);c.drawLine(8,11,12,11,pen);c.drawLine(20,11,24,11,pen);}else if(kind==2){c.drawLine(9,23,25,5,pen);c.drawLine(13,26,28,9,pen);c.drawOval(new RectF(4,21,14,29),pen);}else if(kind==3||kind==7){c.drawRoundRect(new RectF(3,6,29,27),4,4,pen);if(kind==7)c.drawCircle(16,16,6,pen);else{c.drawCircle(10,12,2,pen);Path path=new Path();path.moveTo(5,24);path.lineTo(14,15);path.lineTo(20,21);path.lineTo(25,17);path.lineTo(28,24);c.drawPath(path,pen);}}else if(kind==4){c.drawRoundRect(new RectF(3,9,29,25),6,6,pen);c.drawLine(8,17,16,17,pen);c.drawLine(12,13,12,21,pen);c.drawCircle(23,16,1,pen);}else if(kind==6){c.save();c.rotate(-30,16,16);c.drawOval(new RectF(2,10,30,22),pen);c.restore();c.drawCircle(16,16,7,pen);}else if(kind==5||kind==8){c.drawRoundRect(new RectF(6,3,26,29),3,3,pen);for(int y=10;y<25;y+=6)c.drawLine(10,y,22,y,pen);}else if(kind==9){c.drawCircle(16,16,11,pen);c.drawCircle(16,16,4,pen);}else{for(int y=5;y<25;y+=13)for(int x=5;x<25;x+=13)c.drawRoundRect(new RectF(x,y,x+9,y+9),2,2,pen);}c.restore();}}
}
